TLM.f("Sancti/12-03",{"officium":"S. Francisci Xaverii Confessoris","rule":["vide C5;","Gloria"],"fallback":"Commune/C5","from":{"Graduale":"Commune/C5","GradualeP":"Commune/C5","Tractus":"Commune/C5"},"sections":{"Introitus":[{"k":"ref","la":"Ps 118:46-47"},{"k":"text","la":"Loquébar de testimóniis tuis in conspéctu regum, et non confundébar: et meditábar in mandátis tuis, quæ diléxi nimis."},{"k":"ref","la":"Ps 116:1-2"},{"k":"text","la":"Laudáte Dóminum, omnes gentes, laudáte eum, omnes pópuli: quóniam confirmáta est super nos misericórdia ejus, et véritas Dómini manet in ætérnum."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Loquébar de testimóniis tuis in conspéctu regum, et non confundébar: et meditábar in mandátis tuis, quæ diléxi nimis."}],"Oratio":[{"k":"text","la":"Deus, qui Indiárum gentes beáti Francísci prædicatióne et miráculis Ecclésiæ tuæ aggregáre voluísti: concéde propítius; ut, cujus gloriósa mérita venerámur, virtútum quoque imitémur exémpla."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Romános"},{"k":"ref","la":"Rom 10:10-18"},{"k":"text","la":"Fratres: Corde enim créditur ad justítiam: ore autem conféssio fit ad salútem. Dicit enim Scriptúra: Omnis, qui credit in illum, non confundétur. Non enim est distínctio Judǽi et Græci: nam idem Dóminus ómnium, dives in omnes, qui ínvocant illum. Omnis enim, quicúmque invocáverit nomen Dómini, salvus erit. Quómodo ergo invocábunt, in quem non credidérunt? Aut quómodo credent ei, quem non audiérunt? Quómodo autem áudient sine prædicánte? Quómodo vero prædicábunt, nisi mittántur? sicut scriptum est: Quam speciósi pedes evangelizántium pacem, evangelizándum bona! Sed non omnes obédiunt Evangélio. Isaías enim dicit: Dómine, quis crédidit audítui nostro? Ergo fides ex audítu, audítus autem per verbum Christi. Sed dico: Numquid non audiérunt? Et quidem in omnem terram exívit sonus eórum, et in fines orbis terræ verba eórum."}],"Graduale":[{"k":"ref","la":"Ps 91:13; 91:14"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini."},{"k":"ref","la":"Ps 91:3"},{"k":"text","la":"Ad annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem. Allelúja, allelúja"},{"k":"ref","la":"Ja 1:12"},{"k":"text","la":"Beátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Jas 1:12"},{"k":"text","la":"Beátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja."},{"k":"ref","la":"Eccli 45:9"},{"k":"text","la":"Amávit eum Dóminus et ornávit eum: stolam glóriæ índuit eum. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 91:13; 91:14"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini."},{"k":"ref","la":"Ps 91:3"},{"k":"text","la":"Ad annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem."},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Marcum"},{"k":"ref","la":"Marc 16:15-18"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Eúntes in mundum univérsum, prædicáte Evangélium omni creatúræ. Qui credíderit, et baptizátus fúerit, salvus erit: qui vero non credíderit, condemnábitur. Signa autem eos, qui credíderint, hæc sequéntur: In nómine meo dæmónia ejícient: linguis loquéntur novis: serpéntes tollent: et si mortíferum quid bíberint, non eis nocébit: super ægros manus impónent, et bene habébunt."}],"Offertorium":[{"k":"ref","la":"Ps 88:25"},{"k":"text","la":"Véritas mea et misericórdia mea cum ipso: et in nómine meo exaltábitur cornu ejus. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Præsta nobis, quǽsumus, omnípotens Deus: ut nostræ humilitátis oblátio et pro tuórum tibi grata sit honóre Sanctórum, et nos córpore páriter et mente puríficet."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 24:46-47"},{"k":"text","la":"Beátus servus, quem, cum vénerit dóminus, invénerit vigilántem: amen, dico vobis, super ómnia bona sua constítuet eum. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Quǽsumus, omnípotens Deus: ut, qui cœléstia aliménta percépimus, intercedénte beáto Francísco Confessóre tuo, per hæc contra ómnia advérsa muniámur."},{"k":"macro","name":"Per Dominum"}]},"hr":{"c6936f973dfa6a15":{"t":"Ps 118, 46-47, Ps 116, 1-2\n(Ps 118, 46-47) Govorio sam pred kraljevima o tvojim odredbama i nisam se smeo, i razmišljao sam o tvojim zapovijedima koje veoma ljubim. (Ps 116, 1-2). Hvalite Gospodina, sva plemena, hvalite ga, svi narodi, jer je silno nad nama milosrđe njegovo i istina Gospodnja ostaje do vijeka.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 118, 46-47) Govorio sam pred kraljevima o tvojim odredbama i nisam se smeo, i razmišljao sam o tvojim zapovijedima koje veoma ljubim."},"8cacb83e21125296":{"t":"<i>Pomolimo se</i>.\nBože, koji si htio pridružiti svojoj Crkvi indijske narode propovijedanjem i čudesima blaženoga Franje, daj blagostivo, da nasljedujemo kreposne primjere onoga kojega slavne zasluge častimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"d36a86a61c51dfad":{"t":"Rim 10, 10-18\nČitanje Poslanice bl. Pavla apostola Rimljanima. Braćo: Srcem se vjeruje za opravdanje, a ustima se ispovijeda vjera za spas. Jer Pismo kaže: »Neće se postidjeti nijedan koji vjeruje u njega.« A nema razlike među Židovom i Grkom, jer je isti Gospodin svih bogat za sve koji ga prizivaju. A spasit će se svaki koji god bude prizvao Gospodina. Nego, kako će prizivati onog u koga nisu vjerovali? Ili kako će vjerovati u onoga o kojemu nisu čuli? Kako će čuti bez propovjednika? Kako će propovijedati ako nisu poslani? Kao što je pisano: »Kako su krasne noge onih koji navješćuju mir, koji navješćuju dobro!« Ali se svi ne pokoravaju evanđelju, kako kaže Izaija: »Gospodine, tko vjeruje našemu propovijedanju?« Dakle, vjera je od propovijedanja, a propovijeda se po Kristovoj zapovijedi. Nego pitam vas: Zar nisu čuli? Ta po svoj se zemlji razliježe njihov glas i njihove riječi do na kraj svijeta."},"929d73ef8c983301":{"t":"Ps 91, 13-14, Ps 91, 3\n(Ps 91, 13-14) Kao palma cvjeta i kao libanski cedar raste pravednik u domu Gospodnjem. (Ps 91, 3) Jutrom naviješta milosrđe tvoje i noću tvoju vjernost.\n\nJak 1, 12\n<i>Aleluja</i>, <i>aleluja</i>.\nBlago čovjeku koji nadvlada napast, jer kad bude prokušan, primit će krunu života. <i>Aleluja</i>."},"0fe0dcc5ad8be021":{"t":"Mk 16, 15-18\nSlijedi sveto Evanđelje po Marku. U ono vrijeme reče Isus svojim učenicima: Pođite po svem svijetu i propovijedajte Evanđelje svakome stvoru. Tko bude vjerovao i krstio se, spasit će se, a tko ne bude vjerovao, bit će osuđen. A one koji budu vjerovali pratit će ova čudesa: u moje ime izgonit će đavle, govorit će novim jezicima, rukama će uzimati zmije, i ako što smrtonosna popiju, neće im naškoditi, na bolesnike će polagati ruke i oni će ozdravljati."},"88bea9a296c140ac":{"t":"Ps 88, 25\nMoja će vjernost i moje milosrđe biti s njime, i svojim ću imenom uzdići njegovu moć."},"1e8de8be36cd864e":{"t":"Daj nam, molimo, svemogući Bože, da naš ponizni prinos bude tebi drag zbog časti tvojih svetih,i neka očisti naše tijelo i dušu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"56842ed674d6e163":{"t":"Mt 24, 46-47\nBlago slugi koga gospodar nađe budna, kad dođe. Zaista vam kažem: Postavit će ga nad svim imanjem svojim."},"241a79b143cc072e":{"t":"<i>Pomolimo se</i>.\nMolimo, svemogući Bože, da nas nebeska hrana koju smo primili zagovorom blaženoga Franje, tvoga priznavaoca zaštiti od svih protivnosti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}},"variants":{"paschal":{"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Jas 1:12"},{"k":"text","la":"Beátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja"},{"k":"ref","la":"Eccli 45:9"},{"k":"text","la":"Amávit eum Dóminus et ornávit eum: stolam glóriæ índuit eum. Allelúja."}]}}});
